import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null && !line.trim().isEmpty()) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length < 3) continue;
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            int MOD = Integer.parseInt(parts[2]);

            // Read next line if needed
            // Since input may be on multiple lines, read until we have all three
            while (parts.length < 3) {
                line = br.readLine();
                parts = line.trim().split("\\s+");
            }

            // Initialize combination table C
            int[][] C = new int[m + 1][m + 1];
            for (int i = 0; i <= m; i++) {
                C[i][0] = 1;
                for (int j = 1; j <= i; j++) {
                    C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
                    if (C[i][j] >= MOD) C[i][j] -= MOD;
                }
            }

            int[] sum_n = new int[m + 1];
            int[] total_sum = new int[m + 1];
            int[] ways = new int[m + 1];
            int[] sum = new int[m + 1];

            sum_n[0] = 0;
            for (int i = 1; i <= m; i++) {
                sum_n[i] = sum_n[i - 1] + i;
            }

            ways[0] = 1;
            for (int size = 1; size <= m; size++) {
                for (int split = 0; split < size; split++) {
                    int left = split;
                    int right = size - 1 - split;
                    long prod = ((long) ways[left] * ways[right]) % MOD;

                    // Update ways[size]
                    long addWays = ((long) (size + 1) * C[size - 1][split]) % MOD;
                    addWays = (addWays * prod) % MOD;
                    ways[size] = (int) ((ways[size] + addWays) % MOD);

                    // sum_part calculations
                    long sum_part = 0;
                    sum_part = (sum_part + ((long) sum[left] * ways[right]) % MOD) % MOD;
                    sum_part = (sum_part + ((long) sum[right] * ways[left]) % MOD) % MOD;

                    // Update sum[size]
                    long addSum = ((long) (size + 1) * C[size - 1][split]) % MOD;
                    addSum = (addSum * sum_part) % MOD;
                    sum[size] = (int) ((sum[size] + addSum) % MOD);

                    // total_sum_part calculations
                    long total_sum_part = 0;
                    total_sum_part = (total_sum_part + ((long) sum_n[left] * ways[right]) % MOD) % MOD;
                    total_sum_part = (total_sum_part + ((long) sum_n[right] * ways[left]) % MOD) % MOD;

                    // Update sum[size] with total_sum_part
                    long addTotalSum = ((long) (size + 1) * C[size - 1][split]) % MOD;
                    addTotalSum = (addTotalSum * total_sum_part) % MOD;
                    sum[size] = (int) ((sum[size] + addTotalSum) % MOD);
                }
            }

            int[][] ways2 = new int[n + 1][m + 1];
            int[][] sum2 = new int[n + 1][m + 1];

            ways2[0][0] = 1;
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j <= Math.min(i, m); j++) {
                    ways2[i][j] = ways2[i - 1][j];
                    sum2[i][j] = sum2[i - 1][j];
                    for (int k = 1; k <= j; k++) {
                        int ni = Math.max(0, i - k - 1);
                        int nj = j - k;
                        long ways_k = ways[k];
                        long ways_ni_nj = ways2[ni][nj];
                        long c = C[j][k];

                        long addWays2 = (ways_k * ways_ni_nj) % MOD;
                        addWays2 = (addWays2 * c) % MOD;
                        ways2[i][j] = (int) ((ways2[i][j] + addWays2) % MOD);

                        long sum_k = sum[k];
                        long sum_ni_nj = sum2[ni][nj];

                        long addSum2 = ((sum_k * ways_ni_nj) % MOD + (ways_k * sum_ni_nj) % MOD) % MOD;
                        addSum2 = (addSum2 * c) % MOD;
                        sum2[i][j] = (int) ((sum2[i][j] + addSum2) % MOD);
                    }
                }
            }

            System.out.println(sum2[n][m]);
        }
    }
}
